const ipmb_schema_field_t* ipmb_schema_lookup(int field_id) {
    for (int i = 0; ipmb_global_schema_registry[i].field_id != 0; i++) {
        if (ipmb_global_schema_registry[i].field_id == field_id) {
            return &ipmb_global_schema_registry[i];
        }
    }
    return NULL;
}
